#!/usr/bin/env python3
"""Render the DIMENSION-01 saved summary and a small analytic 2D illustration."""
from __future__ import annotations
import argparse,html,json
from pathlib import Path
COLORS=('#3b82f6','#22c55e','#f59e0b','#ef4444','#8b5cf6')
def main():
 p=argparse.ArgumentParser();p.add_argument('--bundle',required=True,type=Path);a=p.parse_args();b=a.bundle.resolve(strict=True)
 m=json.loads((b/'manifest.json').read_text());s=json.loads((b/'summary.json').read_text());rows=[];shapes=[]
 for c in s['cases']:
  sa=c['strategies']['csl.synthesis.reach-back'];sb=c['strategies']['csl.synthesis.strategy-b']
  def ms(v):return '—' if v is None else f'{v/1e6:.3f} ms'
  rows.append(f"<tr><th>n={c['state_dimension']}, T={c['horizon']}</th><td>{ms(sa['median_ns'])} ({ms(sa['min_ns'])}–{ms(sa['max_ns'])})</td><td>{ms(sb['median_ns'])} ({ms(sb['min_ns'])}–{ms(sb['max_ns'])})</td><td>{c['verified_measured_attempts']}/12</td><td>{c['verified_paired_repetitions']}/6</td></tr>")
  for label,obj in (('Reach-back',sa),('Strategy B',sb)):
   x=obj['representation_shape'] or {};shapes.append(f"<tr><th>n={c['state_dimension']}, T={c['horizon']}</th><td>{label}</td><td>{x.get('joint_coordinates','—')}</td><td>{x.get('inequality_rows','—')}</td><td>{x.get('equality_rows','—')}</td><td>{x.get('nonzero_h_coefficients','—')}</td></tr>")
 svg=[]; ox,oy,size=90,350,220; unit=size/4
 svg.append('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 620 430" role="img" aria-labelledby="title desc"><title id="title">Analytic 2D forward and backward sets for the T=4 vector integrator</title><desc id="desc">Nested forward boxes R0 through R4, backward singleton sets and their intersections at zero, and the zero optimal trajectory. This is an analytic illustration, not an algorithm trace.</desc><rect width="620" height="430" fill="#fff"/><text x="30" y="32" font-family="sans-serif" font-size="18" font-weight="bold">T=4 analytic state-space illustration</text>')
 svg.append(f'<path d="M{ox} {oy-size}V{oy}H{ox+size}" fill="none" stroke="#334155" stroke-width="2"/><text x="{ox+size+8}" y="{oy+5}" font-family="sans-serif" font-size="14">x₁</text><text x="{ox-12}" y="{oy-size-10}" font-family="sans-serif" font-size="14">x₂</text>')
 for k in range(1,5):
  side=k*unit; y=oy-side
  svg.append(f'<rect x="{ox}" y="{y}" width="{side}" height="{side}" fill="{COLORS[k]}" fill-opacity="0.12" stroke="{COLORS[k]}" stroke-width="2"/>')
  svg.append(f'<text x="{ox+side-46}" y="{y+17}" font-family="sans-serif" font-size="12" fill="{COLORS[k]}">R{k}</text>')
 svg.append(f'<circle cx="{ox}" cy="{oy}" r="6" fill="#111827"/><text x="{ox+12}" y="{oy-12}" font-family="sans-serif" font-size="12">G₀…G₄ = Rₖ∩Gₖ = {"(0,0)"}</text>')
 for k in range(5):
  x=ox+k*size/4
  svg.append(f'<circle cx="{x}" cy="{oy}" r="3" fill="#111827"/>')
 for k in range(5):
  svg.append(f'<text x="{ox+size+35}" y="{45+k*22}" font-family="sans-serif" font-size="12" fill="{COLORS[k]}">R{k}: [0,{k}]²</text>')
 svg.append('<text x="30" y="405" font-family="sans-serif" font-size="12" fill="#475569">Analytic geometry from A=I, B=I, 0≤u≤1. Forward/backward layers are explanatory, not saved strategy iterates.</text></svg>')
 (b/'state-space-illustration.svg').write_text(''.join(svg))
 env=m['environment'];sourcehash=html.escape(json.dumps(env['measurement_source_sha256'],sort_keys=True))
 page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>REVIEW-05 dimension pilot</title><style>body{{max-width:1080px;margin:2rem auto;padding:0 1rem;font:16px/1.55 system-ui;color:#17212b}}h1,h2{{line-height:1.2}}.note{{padding:1rem;background:#fff5dd;border-left:4px solid #bb7900}}table{{border-collapse:collapse;width:100%;margin:1rem 0}}th,td{{padding:.5rem;border:1px solid #aab4c0;text-align:left}}img{{width:min(100%,760px);height:auto}}code{{overflow-wrap:anywhere}}</style></head><body><h1>REVIEW-05: matched vector-state horizon pilot</h1><p>This new-comparison experiment runs reach-back and Strategy B on a vector integrator at state/control dimensions n=1,2 and horizons T=2,4. Controls satisfy 0≤uᵢ≤1; the state box is [-T,T]ⁿ at every stage; x₀=0; the terminal objective is minimize sumᵢ xᵢ[T].</p><p class="note"><strong>Scope:</strong> every row below is included only when both strategies' emitted H relations pass the exact fixture-specific oracle. This proves the unique all-zero optimal history only for these four fixtures. It is not a general completeness, winner, speedup, or complexity claim.</p><h2>Verified paired timings</h2><table><thead><tr><th>Case</th><th>Reach-back median (range)</th><th>Strategy B median (range)</th><th>Verified attempts</th><th>Verified pairs</th></tr></thead><tbody>{''.join(rows)}</tbody></table><p>Timing covers <code>SynthesisWorkspace::run()</code>; process launch/setup are excluded. One excluded warmup pair and six alternating measured pairs were attempted per case. Bounds are 300 s CPU, 8 GiB address space, and 300 s wall time per strategy process; one backend thread and one driver worker were requested. Raw output, failures, attempts, and checks are retained in the bundle.</p><h2>Candidate relation growth</h2><table><thead><tr><th>Case</th><th>Strategy</th><th>Joint coordinates</th><th>Inequality rows</th><th>Equality rows</th><th>Nonzero H coefficients</th></tr></thead><tbody>{''.join(shapes)}</tbody></table><p>Coefficient counts are not allocated-byte measurements. The experiment varies state/control dimension, horizon and explicit stage-state bounds together; the factorial cases expose their observed relation-size effects but do not isolate sparse assembly, factorization, conversion, family-query, RSS or phase costs.</p><h2>Minimal supported 2D visual</h2><p>The saved 2D geometry below is computed analytically from the fixture; it illustrates the state coordinates and exact forward/backward reachability of the zero-optimum case. It is not a trace of internal strategy iterates.</p><figure><a href="state-space-illustration.svg"><img src="state-space-illustration.svg" alt="Nested two-dimensional forward reachable boxes with backward sets and intersections at zero"></a><figcaption><a href="state-space-illustration.svg">Download SVG</a></figcaption></figure><h2>Reproducibility</h2><p>Source revision <code>{html.escape(env['source_revision'])}</code>, binary SHA-256 <code>{html.escape(env['binary_sha256'])}</code>. Build provenance: <a href="build-provenance.json">JSON</a>. Attempts: <a href="attempts.jsonl">JSONL</a>; checks: <a href="checks.jsonl">JSONL</a>; summary: <a href="summary.json">JSON</a>; fixtures: <a href="inputs/dimension01-n1-t2.json">n=1,T=2</a>, <a href="inputs/dimension01-n1-t4.json">n=1,T=4</a>, <a href="inputs/dimension01-n2-t2.json">n=2,T=2</a>, <a href="inputs/dimension01-n2-t4.json">n=2,T=4</a>; hashes: <a href="SHA256SUMS">SHA256SUMS</a>.</p><p>Measurement source hashes: <code>{sourcehash}</code></p></body></html>'''
 (b/'index.html').write_text(page)
 print(b/'index.html');return 0
if __name__=='__main__': raise SystemExit(main())
